import { useState } from "react";
import React from "react";
// import { handleProfileClick } from "../utils/someFile";
const Menu = () => {
  let [selectedMenue, setselectedMenue] = useState(2);
  function handleClickMenue(e, a) {
    selectedMenue((selectedMenue) => {
      selectedMenue = a;
    });
  }
  return (
    <div className="menu-container">
      <img src="logo.png" style={{ width: "40px" }} />
      <div className="menus">
        <ul>
          <li data-value={1} onClick={() => handleClickMenue(1)}>
            <a
              href="/"
              style={{
                textDecoration: "none",
                color: selectedMenue === 1 ? "blue" : "black",
              }}
            >
              <p>Dashboard</p>
            </a>
          </li>
          <li
            value={1}
            onClick={() => {
              handleClickMenue(2);
            }}
          >
            <a
              href="/orders"
              style={{ textDecoration: "none", color: "black" }}
            >
              <p>Orders</p>
            </a>
          </li>
          <li
            value={3}
            onClick={() => {
              handleClickMenue(3);
            }}
          >
            <a
              href="/holdings"
              style={{ textDecoration: "none", color: "black" }}
            >
              <p>Holdings</p>
            </a>
          </li>
          <li
            value={4}
            onClick={() => {
              handleClickMenue(4);
            }}
          >
            <a
              href="positions"
              style={{ textDecoration: "none", color: "black" }}
            >
              <p>Positions</p>
            </a>
          </li>
          <li
            value={5}
            onClick={() => {
              handleClickMenue(5);
            }}
          >
            <a href="funds" style={{ textDecoration: "none", color: "black" }}>
              <p>Funds</p>
            </a>
          </li>
          <li
            value={6}
            onClick={() => {
              handleClickMenue(6);
            }}
          >
            <a href="apps" style={{ textDecoration: "none", color: "black" }}>
              <p>Apps</p>
            </a>
          </li>
        </ul>
        <hr />

        <div className="avatar">ZU</div>
        <p className="username">USERID</p>
      </div>
    </div>
  );
};

export default Menu;
